SELECT
    COUNT(*)
FROM
trade_order_info


        create_time BETWEEN #{startTime} AND #{endTime}


        and order_sale_id = #{saleId}

SELECT sum(pct.order_payment_amount) FROM trade_order_info toi inner join pay_consume_trade pct on toi.order_id = pct.order_id
pct.trade_is_paid IN (3012, 3013)
and toi.create_time BETWEEN #{startTime} AND #{endTime}
and toi.order_sale_id = #{saleId}
